DAX Formula:
CALCULATE(
MIN(CVIP_POPSTATUS2[FIRST_VACC_ACTIVITY_DATE])
)

CALCULATE(
MAX(CVIP_POPSTATUS2[LAST_VACC_ACTIVITY_DATE])
)

CALCULATE(COUNT(CVIP_POPSTATUS2[OBS_NHI]),
	USERELATIONSHIP(CVIP_POPSTATUS2[FIRST_VACC_ACTIVITY_DATE],
		xd_Calendar[Calendar]
		)
	)

//Reference 1: https://learn.microsoft.com/en-us/dax/userelationship-function-dax
//Reference 2: https://community.fabric.microsoft.com/t5/Desktop/multiple-dates-on-axis/td-p/2484359/page/2

CALCULATE(COUNT(CVIP_POPSTATUS2[OBS_NHI]),
	USERELATIONSHIP(CVIP_POPSTATUS2[FULLY_VACCINATED_ACTIVITY_DATE],
		xd_Calendar[Calendar]
		)
	)

//Reference 1: https://learn.microsoft.com/en-us/dax/userelationship-function-dax
//Reference 2: https://community.fabric.microsoft.com/t5/Desktop/multiple-dates-on-axis/td-p/2484359/page/2

CALCULATE(COUNT(CVIP_POPSTATUS2[OBS_NHI]),
	USERELATIONSHIP(CVIP_POPSTATUS2[ELIGIBLE_FOR_DOSE2_DATE],
		xd_Calendar[Calendar]
		)
)

//Reference 1: https://learn.microsoft.com/en-us/dax/userelationship-function-dax
//Reference 2: https://community.fabric.microsoft.com/t5/Desktop/multiple-dates-on-axis/td-p/2484359/page/2

CALCULATE(COUNT(CVIP_POPSTATUS2[OBS_NHI]),
	USERELATIONSHIP(CVIP_POPSTATUS2[LAST_VACC_ACTIVITY_DATE],
		xd_Calendar[Calendar]
		)
	)

//Reference 1: https://learn.microsoft.com/en-us/dax/userelationship-function-dax
//Reference 2: https://community.fabric.microsoft.com/t5/Desktop/multiple-dates-on-axis/td-p/2484359/page/2

CALCULATE(COUNT(CVIP_POPSTATUS2[OBS_NHI]),
	USERELATIONSHIP(CVIP_POPSTATUS2[LATEST_ADDITIONAL_BOOSTER_DATE],
		xd_Calendar[Calendar]
		)
	)

//Reference 1: https://learn.microsoft.com/en-us/dax/userelationship-function-dax
//Reference 2: https://community.fabric.microsoft.com/t5/Desktop/multiple-dates-on-axis/td-p/2484359/page/2

//Cummulative Count of NHI Fully Vaccinated
CALCULATE([#NHI Fully Vaccinated]
    ,FILTER(
        ALL(CVIP_POPSTATUS2),
        CVIP_POPSTATUS2[FULLY_VACCINATED_ACTIVITY_DATE] <= MAX(CVIP_POPSTATUS2[FULLY_VACCINATED_ACTIVITY_DATE])
    )
)

//Cummulative Count of NHI Partially Vaccinated
CALCULATE([#NHI Partially Vaccinated]
    ,FILTER(
        ALL(CVIP_POPSTATUS2),
        CVIP_POPSTATUS2[FIRST_VACC_ACTIVITY_DATE] <= MAX(CVIP_POPSTATUS2[FIRST_VACC_ACTIVITY_DATE])
    )
)

//Cummulative Count of NHI Reset by Fully and Partial Vaccinated
CALCULATE([#NHI Fully Vaccinated]
    ,FILTER(
        ALL(CVIP_POPSTATUS2),
        CVIP_POPSTATUS2[VACCINATION_STATUS_SK] = MAX(CVIP_POPSTATUS2[VACCINATION_STATUS_SK])
	&& CVIP_POPSTATUS2[FULLY_VACCINATED_ACTIVITY_DATE] <= MAX(CVIP_POPSTATUS2[FULLY_VACCINATED_ACTIVITY_DATE])
    )
)

CALCULATE(
        DISTINCTCOUNT(f_AllVacc_PQ[NHI_DOB])

        )

CALCULATE([#NHI_DOB],
	//USERELATIONSHIP(f_AllVacc_PQ[FIRST_VACC_ACTIVITY_DATE],
    USERELATIONSHIP(f_AllVacc_PQ[_Date2],
		d_Calendar[Calendar]
		)
        ,FILTER(
        ALL(f_AllVacc_PQ[_VaccinationStatus_Flag]),
        f_AllVacc_PQ[_VaccinationStatus_Flag] = "Partially Vaccinated")

	)

//Reference 1: https://learn.microsoft.com/en-us/dax/userelationship-function-dax
//Reference 2: https://community.fabric.microsoft.com/t5/Desktop/multiple-dates-on-axis/td-p/2484359/page/2))))

CALCULATE([#NHI_DOB],
	//USERELATIONSHIP(f_AllVacc_PQ[FULLY_VACCINATED_ACTIVITY_DATE],
    USERELATIONSHIP(f_AllVacc_PQ[_Date2],
		d_Calendar[Calendar]
		)
        ,FILTER(
        ALL(f_AllVacc_PQ[_VaccinationStatus_Flag]),
        f_AllVacc_PQ[_VaccinationStatus_Flag] = "Fully Vaccinated")
	)

//Reference 1: https://learn.microsoft.com/en-us/dax/userelationship-function-dax
//Reference 2: https://community.fabric.microsoft.com/t5/Desktop/multiple-dates-on-axis/td-p/2484359/page/2))))

CALCULATE([#NHI_DOB],
	USERELATIONSHIP(f_AllVacc_PQ[_DWH_EFFECTIVE_FROM_DATE],
		d_Calendar[Calendar]
		)
        ,FILTER(
        ALL(f_AllVacc_PQ[_VaccinationStatus_Flag]),
        f_AllVacc_PQ[_VaccinationStatus_Flag] = "Unvaccinated")
	)

//Reference 1: https://learn.microsoft.com/en-us/dax/userelationship-function-dax
//Reference 2: https://community.fabric.microsoft.com/t5/Desktop/multiple-dates-on-axis/td-p/2484359/page/2))))

var _count1 = 
CALCULATE(DISTINCTCOUNT(f_AllVacc_PQ[_NHI_DOB_1stVACC])
        ,FILTER(
        ALL(d_VaccStatus[VACC_STATUS_SK]),
        d_VaccStatus[VACC_STATUS_SK] IN{1001, 1003})            //Use code instead of "Partially Vaccinated" and "Fully Vaccinated", which both received teh 1st dose
)

var _count2 = 
CALCULATE(_count1,
	USERELATIONSHIP(f_AllVacc_PQ[FIRST_VACC_ACTIVITY_DATE],
		d_Calendar[Calendar]
		)
)


return _count2

//Reference 1: https://learn.microsoft.com/en-us/dax/userelationship-function-dax
//Reference 2: https://community.fabric.microsoft.com/t5/Desktop/multiple-dates-on-axis/td-p/2484359/page/2))))

var _count1 = 
