        ,FILTER(
        ALL(d_VaccStatus[VACC_STATUS_SK]),
        d_VaccStatus[VACC_STATUS_SK] IN{1001})            //Use code instead of "Fully Vaccinated"
)

var _count2 = 
CALCULATE(_count1,
	USERELATIONSHIP(f_AllVacc_PQ[FULLY_VACCINATED_ACTIVITY_DATE],
