        ,FILTER(
        ALL(d_VaccStatus[VACC_STATUS_SK]),
        d_VaccStatus[VACC_STATUS_SK] IN{1001})            //Use code instead of "Fully Vaccinated"; all who had 1st booster are already fully vaccinated (received 2 doses prior to booseter)
)

var _count2 = 
CALCULATE(_count1,
	USERELATIONSHIP(f_AllVacc_PQ[FIRST_BOOSTER_ACTIVITY_DATE],
