//Reference 1: https://learn.microsoft.com/en-us/dax/userelationship-function-dax
//Reference 2: https://community.fabric.microsoft.com/t5/Desktop/multiple-dates-on-axis/td-p/2484359/page/2))))

//Cummulative Count of NHI Partially Vaccinated
CALCULATE([Cnt_NHI_PartVacc]
    ,FILTER(
        ALL(f_AllVacc_PQ),
        f_AllVacc_PQ[_Date2] <= MAX(f_AllVacc_PQ[_Date2])
    )
)

//Cummulative Count of NHI Partially Vaccinated
CALCULATE([Cnt_NHI_FullVacc]
    ,FILTER(
        ALL(f_AllVacc_PQ),
        f_AllVacc_PQ[_Date2] <= MAX(f_AllVacc_PQ[_Date2])
    )
)

//Cummulative Count of NHI Partially Vaccinated
CALCULATE([Cnt_NHI_UnVacc]
    ,FILTER(
        ALL(f_AllVacc_PQ),
        f_AllVacc_PQ[_Date2] <= MAX(f_AllVacc_PQ[_Date2])
    )
)

//Cummulative Count of NHI with 1 dose
CALCULATE([Cnt_NHI_1doseVacc]
    ,FILTER(
        ALL(f_AllVacc_PQ),
        f_AllVacc_PQ[_Date2] <= MAX(f_AllVacc_PQ[_Date2])
    )
)

//Cummulative Count of NHI with 1 dose
CALCULATE([Cnt_NHI_2doseVacc]
    ,FILTER(
        ALL(f_AllVacc_PQ),
        f_AllVacc_PQ[_Date2] <= MAX(f_AllVacc_PQ[_Date2])
    )
)

//Cummulative Count of NHI with 1 dose
CALCULATE([Cnt_NHI_3doseVacc]
    ,FILTER(
        ALL(f_AllVacc_PQ),
        f_AllVacc_PQ[_Date2] <= MAX(f_AllVacc_PQ[_Date2])
    )
)

//Cummulative Count of NHI with 1 dose
CALCULATE([Cnt_NHI_4doseVacc]
    ,FILTER(
        ALL(f_AllVacc_PQ),
        f_AllVacc_PQ[_Date2] <= MAX(f_AllVacc_PQ[_Date2])
    )
)

//Cummulative Count
CALCULATE([$Budget]
    ,FILTER(
        ALLSELECTED(f_Project),
        f_Project[Date_DBC] <= MAX(f_Project[Date_DBC])

    )
)

CALCULATE(
        [$Budget_InProgress] * (1+ [Prm_AdjustBudget Value]/100)    //value increased based on paramter value


        )

//Cummulative Count
CALCULATE([$Budget_Adjust]
    ,FILTER(
        ALLSELECTED(f_Project),
        f_Project[Date_DBC] <= MAX(f_Project[Date_DBC])
        //&& f_Project[Business Priority] = MAX(f_Project[Business Priority])
    )
)

//Cummulative Count for Status In Progress only
CALCULATE([$Budget_InProgress]
    ,FILTER(
        ALLSELECTED(f_Project),
        f_Project[Date_DBC] <= MAX(f_Project[Date_DBC])

    )
)

//Cummulative Count
CALCULATE([New_$Budget]
    ,FILTER(
        ALLSELECTED(f_Project),
        f_Project[Date_DBC] <= MAX(f_Project[Date_DBC])

    )
)

CALCULATE(
        [$Budget_InProgress] * ([Prm_AdjustBudget Value]/100)    //value increased based on paramter value


        )

//Cummulative Count
CALCULATE([Cum_New_$Budget] + [Cum_$Budget]
    ,FILTER(ALL(f_Project[Date_DBC])
            ,f_Project[Date_DBC] >= [Today Date]
                )

    )

CALCULATE(
        [$Budget_InProgress] * ([Prm_AdjustBudget Value]/100)    //value increased based on paramter value


        ) + 0

//Cummulative Count for Status In Progress only
[$Budget_InProgress_OfToday] +
CALCULATE([$Budget_InProgress_FromToday]
    ,FILTER(
        ALLSELECTED(f_Project),
        f_Project[Date_DBC] < MAX(f_Project[Date_DBC])

    )
)
